#!/usr/bin/env node
// Builds all `themes/*.json` files from `src/palettes/*.json` + `src/theme.js`.
//
// Usage:
//   node src/build.js          # (re)generate theme files
//   node src/build.js --check  # fail if generated files differ from the committed ones
const fs = require('fs');
const path = require('path');

const buildTheme = require('./theme');

const ROOT = path.join(__dirname, '..');
const PALETTES = ['src/palettes/dark.json', 'src/palettes/light.json']
  .map(source => ({ source, ...require(path.join(ROOT, source)) }));
const THEMES_DIR = path.join(ROOT, 'themes');

// VSCode reads theme files as JSONC, so a comment header is fine here.
function header(palette) {
  return [
    '// This file is generated by `npm run build`, do not edit it by hand.',
    `// Layout: \`src/theme.js\`, colors: \`${palette.source}\`.`,
    '',
  ].join('\n');
}

function render(palette) {
  return header(palette) + JSON.stringify(buildTheme(palette), null, 2) + '\n';
}

function main(argv) {
  const check = argv.includes('--check');
  let failed = false;

  for (const palette of PALETTES) {
    const target = path.join(THEMES_DIR, palette.filename);
    const relative = path.relative(process.cwd(), target);
    const content = render(palette);

    if (check) {
      const existing = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
      if (existing === content) {
        console.log(`OK       ${relative}`);
      } else {
        console.error(`OUTDATED ${relative}, run \`npm run build\``);
        failed = true;
      }
    } else {
      fs.mkdirSync(THEMES_DIR, { recursive: true });
      fs.writeFileSync(target, content);
      console.log(`Written  ${relative}`);
    }
  }

  process.exitCode = failed ? 1 : 0;
}

main(process.argv.slice(2));
